import type { Hono } from "hono";
import { find } from "../runtime/store.js";
import { StepError } from "../runtime/step.js";
import type { Breed, Horse, Swipe, Match } from "../types.js";
import { pickCandidates } from "../steps/pick_candidates.js";

export function routeCandidates(app: Hono): void {
  app.get("/horses/:horse/candidates", async (ctx) => {
    try {
      const horse = find("Horse", ctx.req.param("horse")) as Horse | undefined;
      if (!horse) {
        return ctx.json({ error: "not_found" }, 404);
      }
      const horses = await pickCandidates(horse);
      return ctx.json(horses);
    } catch (error) {
      if (error instanceof StepError) {
        return ctx.json({ error: error.code }, error.code === "not_found" ? 404 : 422);
      }
      throw error;
    }
  });
}
